//! Every math symbol LaTeX declares, derived from the declarations themselves:
//! `fontmath.ltx` (kernel), `latexsym.sty`, `amsfonts.sty`/`amssymb.sty`,
//! `stmaryrd.sty` and `mathrsfs.sty` (TeX Live 2026), each command with its
//! math class, symbol font, slot, the Unicode text the engine paints for it
//! and the bundled face that carries that text.
//!
//! GENERATED by `scripts/gen_math_symbols.py`; do not edit by hand. The
//! (font, slot) pair is what pdfLaTeX sets from the TFM; `text` is what the
//! engine's OpenType route paints. `COMPOSITES` are the kernel's `\def`s,
//! which have no single slot and are implemented by hand (`math.rs`).

/// A `\DeclareSymbolFont` name: the four kernel families and the package fonts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SymbolFont {
    /// `operators` (cmr10 at 10pt).
    Operators,
    /// `letters` (cmmi10 at 10pt).
    Letters,
    /// `symbols` (cmsy10 at 10pt).
    Symbols,
    /// `largesymbols` (cmex10 at 10pt).
    LargeSymbols,
    /// `AMSa` (msam10 at 10pt).
    AMSa,
    /// `AMSb` (msbm10 at 10pt).
    AMSb,
    /// `lasy` (lasy10 at 10pt).
    Lasy,
    /// `stmry` (stmary10 at 10pt).
    Stmry,
    /// `rsfs` (rsfs10 at 10pt).
    Rsfs,
}

impl SymbolFont {
    /// The `\DeclareSymbolFont` name.
    pub fn latex_name(self) -> &'static str {
        match self {
            SymbolFont::Operators => "operators",
            SymbolFont::Letters => "letters",
            SymbolFont::Symbols => "symbols",
            SymbolFont::LargeSymbols => "largesymbols",
            SymbolFont::AMSa => "AMSa",
            SymbolFont::AMSb => "AMSb",
            SymbolFont::Lasy => "lasy",
            SymbolFont::Stmry => "stmry",
            SymbolFont::Rsfs => "rsfs",
        }
    }

    /// The 10pt TFM the font is set from.
    pub fn tfm10(self) -> &'static str {
        match self {
            SymbolFont::Operators => "cmr10",
            SymbolFont::Letters => "cmmi10",
            SymbolFont::Symbols => "cmsy10",
            SymbolFont::LargeSymbols => "cmex10",
            SymbolFont::AMSa => "msam10",
            SymbolFont::AMSb => "msbm10",
            SymbolFont::Lasy => "lasy10",
            SymbolFont::Stmry => "stmary10",
            SymbolFont::Rsfs => "rsfs10",
        }
    }

    /// The prefix of the font's name in a pdfTeX PDF (`CMSY10`, `MSAM7`).
    pub fn pdf_prefix(self) -> &'static str {
        match self {
            SymbolFont::Operators => "CMR",
            SymbolFont::Letters => "CMMI",
            SymbolFont::Symbols => "CMSY",
            SymbolFont::LargeSymbols => "CMEX",
            SymbolFont::AMSa => "MSAM",
            SymbolFont::AMSb => "MSBM",
            SymbolFont::Lasy => "LASY",
            SymbolFont::Stmry => "STMARY",
            SymbolFont::Rsfs => "RSFS",
        }
    }
}

/// The `\math<class>` of the declaration (`Alpha` is `\mathalpha`: an
/// ordinary symbol that math alphabets may change).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SymbolClass {
    Ord,
    Op,
    Bin,
    Rel,
    Open,
    Close,
    Punct,
    Alpha,
}

/// Which file declares a command: the kernel, or the package that has to be
/// loaded for it to exist.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Provider {
    Kernel,
    Latexsym,
    Amsfonts,
    Amssymb,
    Stmaryrd,
    Mathrsfs,
    Amsmath,
}

/// The declaration form.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Kind {
    /// `\DeclareMathSymbol`.
    Symbol,
    /// `\DeclareMathDelimiter`: the small variant, then `large` in cmex-like fonts.
    Delimiter,
    /// `\DeclareMathAccent`.
    Accent,
    /// `\DeclareMathRadical`.
    Radical,
}

/// The bundled face whose `cmap` carries every character of a symbol's `text`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Face {
    LatinModernMath,
    NewComputerModernMath,
    /// An empty or private-use `text`: nothing a face paints as such.
    None,
}

#[derive(Debug, PartialEq)]
pub struct MathSymbol {
    /// The command without its backslash, or the single character
    /// (`\DeclareMathSymbol{+}...`) whose `\mathcode` the declaration sets.
    pub name: &'static str,
    /// `name` is a single character whose `\mathcode` the declaration sets,
    /// not a control sequence (`\P` is a command; `P` the letter).
    pub character: bool,
    pub kind: Kind,
    pub class: SymbolClass,
    pub font: SymbolFont,
    pub slot: u8,
    /// The large variant of a delimiter or radical.
    pub large: Option<(SymbolFont, u8)>,
    /// Unicode text: one character, or a base followed by U+0338 when Unicode
    /// has no precomposed negation; empty for pieces without a character.
    pub text: &'static str,
    /// Character width in ems of the 10pt TFM.
    pub width_em: f64,
    pub face: Face,
    pub provider: Provider,
    /// The declaring `file:line`.
    pub source: &'static str,
}

