/// `\DeclareMathAlphabet` / `\DeclareSymbolFontAlphabet`: (command, NFSS
/// encoding/family/series/shape or the symbol font it shares, provider, source).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AlphabetFont {
    Nfss { encoding: &'static str, family: &'static str, series: &'static str, shape: &'static str },
    SymbolFont(&'static str),
}

